ld 2\", CASE n.pos WHEN 1 THEN \"Child 1\" WHEN 2 THEN \"Child 2\" WHEN 3 THEN \"Child 3\" WHEN 4 THEN \"Child 4\" WHEN 5 THEN \"Child 5\" WHEN 6 THEN \"Child 6\" END AS \"Child SKU\", CASE n.pos WHEN 1 THEN \"Child 1 Product Name\" WHEN 2 THEN \"Child 2 Product Name\" WHEN 3 THEN \"Child 3 Product Name\" WHEN 4 THEN \"Child 4 Product Name\" WHEN 5 THEN \"Child 5 Product Name\" WHEN 6 THEN \"Child 6 Product Name\" END AS \"Child Product Name\" FROM public.tuco_kids_combo_sku_mapping CROSS JOIN ( SELECT 1 AS pos UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 ) n WHERE \"Child SKU\" IS NOT NULL AND \"Child SKU\" != \'\' ), PRODUCT_MASTER AS ( select * from ( SELECT upper(replace(SKU,\'`\',\'\')) COMMONSKU, Product_id, upper(product_name) PRODUCT_NAME, upper(category_name) CATEGORY, upper(product_type) PRODUCT_TYPE, upper(SIZE) SIZE, Upper(colour) COLOR, cast(cost as double precision) COST, cast(tax_rate as double precision) TAX_RATE, product_image_url, concat(\'<img src=\"\',concat(product_image_url,\'\"width=\"70\">\')) as Image, model_no, cast(active as int) as is_active, (cost::double precision) as cogs, (mrp::double precision) as mrp, row_number() over (partition by upper(replace(SKU,\'`\',\'\')) order by upper(replace(SKU,\'`\',\'\')) desc) as rw FROM public.Easyecom_Tuco_Kids_product_master ) where rw=1 ) SELECT \"Parent Product Name\" as parent_product_name, \"Parent SKU\" as parent_sku, \"Child SKU\" as child_sku, \"Child Product Name\" as child_praoduct_name, COALESCE( CASE WHEN \"Child Product Name\" ILIKE \'%pack of %\' THEN NULLIF(REGEXP_SUBSTR(\"Child Product Name\", \'pack of\\s*([0-9]+)\', 1, 1, \'ie\'), \'\')::INT WHEN \"Child Product Name\" ILIKE \'% pack%\' THEN NULLIF(REGEXP_SUBSTR(\"Child Product Name\", \'([0-9]+)\\s*pack\', 1, 1, \'ie\'), \'\')::INT WHEN \"Parent Product Name\" ILIKE \'%pack of %\' AND \"Child 1\" IS NOT NULL AND \"Child 1\" != \'\' AND (\"Child 2\" IS NULL OR \"Child 2\" = \'\') THEN NULLIF(REGEXP_SUBSTR(\"Parent Product Name\", \'pack of\\s*([0-9]+)\', 1, 1, \'ie\'), \'\')::INT END, 1 ) as Child_Quantity, pm.category as child_category FROM parent_child_mapping pcm LEFT JOIN PRODUCT_MASTER pm ON pm.commonsku = pcm.\"child sku\" ;",
